{
  "title": "A slow, close-knit Lisbon day",
  "summary": "We stay mostly around the same lively corner of town, with one gentle ride to the riverside and back, so the day feels like a stroll rather than a sprint.",
  "stops": [
    {
      "poi_id": "p1",
      "kind": "activity",
      "must_do_id": "m1",
      "note": "The one must-do: Belém Tower, all history and river light. Kept exactly where it belongs."
    },
    {
      "poi_id": "p5",
      "kind": "activity",
      "must_do_id": null,
      "note": "LX Factory sits right beside Belém, so we swap the far viewpoint for this easy, artsy wander."
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch beside the activities, with proper vegetarian options and no long ride to get there."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "Time Out Market stays, because street food and photo corners make everyone happy in one room."
    },
    {
      "poi_id": "p16",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner a short stroll from the market, vegan and easy for the whole crew."
    },
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": null,
      "note": "Bairro Alto after dark, close by and just lively enough for the night owl without losing the early bird."
    }
  ]
}
